import{_ as l,o as r,c as i,j as e,a,a5 as n}from"./chunks/framework.R-FQ1xZ2.js";const m=JSON.parse('{"title":"Agent 架构全景","description":"把一个 Agent 拆成模型、工具、记忆、规划器、执行器五块，说清谁在什么时候调用谁。","frontmatter":{"title":"Agent 架构全景","description":"把一个 Agent 拆成模型、工具、记忆、规划器、执行器五块，说清谁在什么时候调用谁。"},"headers":[],"relativePath":"diagrams/agent-architecture-overview.md","filePath":"diagrams/agent-architecture-overview.md","lastUpdated":null}'),o={name:"diagrams/agent-architecture-overview.md"};function c(s,t,g,d,h,u){return r(),i("div",null,[...t[0]||(t[0]=[e("h1",{id:"agent-架构全景",tabindex:"-1"},[a("Agent 架构全景 "),e("a",{class:"header-anchor",href:"#agent-架构全景","aria-label":'Permalink to "Agent 架构全景"'},"​")],-1),e("p",null,[e("span",{class:"fig-badge"},"架构图"),a(),e("code",null,"architecture")],-1),e("blockquote",null,[e("p",null,[e("strong",null,"一句话"),a("：把一个 Agent 拆成模型、工具、记忆、规划器、执行器五块，说清谁在什么时候调用谁。")])],-1),e("div",{class:"fig-frame"},[e("iframe",{src:"/fig/agent-architecture-overview.html",title:"Agent 架构全景",loading:"lazy",allowfullscreen:""})],-1),n('<p class="fig-actions"><a href="/fig/agent-architecture-overview.html" target="_blank" rel="noreferrer">在新窗口打开（可缩放 / 切换明暗主题 / 导出图片）</a></p><h2 id="怎么读这张图" tabindex="-1">怎么读这张图 <a class="header-anchor" href="#怎么读这张图" aria-label="Permalink to &quot;怎么读这张图&quot;">​</a></h2><ol><li>先看中间那条主循环：模型产出意图 → 执行器调工具 → 观察结果回灌 → 再决策。</li><li>左右两侧是「给模型看的东西」：左侧是上下文装配（系统提示 + 记忆 + 工具描述），右侧是外部世界（工具、数据源、其他 Agent）。</li><li>注意记忆是被拆成短期与长期两层的——短期进上下文，长期靠检索按需注入，这也是为什么 Agent 的上下文会越跑越长。</li><li>规划器不是每个 Agent 都有。ReAct 式 Agent 把规划融进每一步决策；Plan-and-Execute 才把规划单独抽出来。</li></ol><h2 id="面试口径" tabindex="-1">面试口径 <a class="header-anchor" href="#面试口径" aria-label="Permalink to &quot;面试口径&quot;">​</a></h2><ul><li>「你说说 Agent 到底是什么？」——先给一句定义（LLM 在循环里自主决定调用哪个工具、观察结果、再决策），再按这张图从上往下讲一遍。</li><li>「Agent 和 Chatbot 的区别是什么？」——Chatbot 是一次问答，Agent 是一个有状态、有副作用、有终止条件的循环。</li><li>「为什么需要记忆分层？」——上下文窗口有限且昂贵，近期原文保真、远期压成摘要或向量检索，本质是成本与保真的取舍。</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/learn/kb/l4-agent/">L4 Agent 与工具生态</a></li><li><a href="/learn/diagrams/react-loop.html">ReAct 循环时序</a></li><li><a href="/learn/diagrams/workflow-vs-agent.html">工作流 vs Agent</a></li></ul>',7)])])}const A=l(o,[["render",c]]);export{m as __pageData,A as default};
